/* SeeFood A revision 03. Pure page markup for the design prototype. */
(function () {
  'use strict';

  const languages = { en: 'English', zh: '简体中文', ja: '日本語', ko: '한국어', es: 'Español' };
  const locale = { en: 'en-US', zh: 'zh-CN', ja: 'ja-JP', ko: 'ko-KR', es: 'es-ES' };
  const groups = [
    { key: 'allergies', icon: 'warning', options: ['peanuts', 'shellfish'] },
    { key: 'restrictions', icon: 'leaf', options: ['vegetarian', 'noPork'] },
    { key: 'tastes', icon: 'leaf', options: ['mild', 'light'] }
  ];
  const text = (ui, ...items) => ui.copy(...items);
  const esc = (ui, value) => ui.e(String(value == null ? '' : value));
  const countLabel = (ui, count) => text(ui, `${count} photo${count === 1 ? '' : 's'}`, `${count} 张图片`, `写真 ${count} 枚`, `사진 ${count}장`, `${count} foto${count === 1 ? '' : 's'}`);
  const action = (name, value = '') => `data-action="${name}"${value ? ` data-value="${value}"` : ''}`;
  const currentRecord = state => (state.records || []).find(record => record.id === state.activeRecordId) || (state.records || [])[0];
  const recordTime = record => {
    const value = record.createdAt;
    if (typeof value === 'number') return value;
    const parsed = Date.parse(value || '');
    return Number.isFinite(parsed) ? parsed : 0;
  };
  const orderedRecords = state => [...(state.records || [])].sort((a, b) => recordTime(b) - recordTime(a));
  function formatDate(record, state, ui) {
    const time = recordTime(record);
    return time ? new Intl.DateTimeFormat(locale[state.lang] || 'en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(time)) : text(ui, 'Just created', '刚刚创建', '作成したばかり', '방금 생성', 'Recién creado');
  }
  function mode(state, ui) {
    return `<div class="mode-switch v3-mode" role="group" aria-label="${esc(ui, text(ui, 'Photo type', '图片用途', '写真の種類', '사진 종류', 'Tipo de foto'))}">${['menu', 'dish'].map(kind => `<button ${action('mode', kind)} class="${state.inputMode === kind ? 'active' : ''}" aria-pressed="${state.inputMode === kind}">${ui.icon(kind === 'menu' ? 'book' : 'image', 19)}<span>${ui.t(kind)}</span></button>`).join('')}</div>`;
  }
  function recordStates(record, ui, scenario) {
    const processing = ['processing', 'uploading', 'upload-failed', 'partial'].includes(scenario) ? scenario : record.processing;
    const pending = ['waiting', 'queued', 'uploading', 'processing', 'pending'].includes(processing) || processing === true;
    const failed = ['failed', 'partial', 'upload-failed', 'waiting-upload'].includes(processing);
    const workLabel = processing === 'uploading' ? text(ui, 'Uploading', '上传中', 'アップロード中', '업로드 중', 'Subiendo') : ['upload-failed', 'waiting-upload'].includes(processing) ? ui.t('waitingUpload') : pending ? ui.t('working') : failed ? text(ui, 'Some work unfinished', '部分处理未完成', '一部未完了', '일부 처리 미완료', 'Procesamiento parcial') : text(ui, 'Processing complete', '处理完成', '処理完了', '처리 완료', 'Procesamiento completo');
    const saveFailed = scenario === 'storage-failed' || ['failed', 'error', 'storage-failed'].includes(record.saveState);
    const saving = ['saving', 'pending', 'unsaved'].includes(record.saveState);
    const saveLabel = saveFailed ? text(ui, 'Save failed', '保存失败', '保存に失敗', '저장 실패', 'Error al guardar') : saving ? text(ui, 'Saving', '保存中', '保存中', '저장 중', 'Guardando') : ui.t('offlineAvailable');
    return `<div class="v3-record-states"><span class="${failed ? 'has-warning' : ''}">${ui.icon(pending ? 'refresh' : failed ? 'warning' : 'check', 13)}${workLabel}</span><span class="${saveFailed ? 'has-warning' : ''}">${ui.icon(saveFailed ? 'warning' : saving ? 'refresh' : 'check', 13)}${saveLabel}</span></div>`;
  }
  function recordRow(record, state, ui, manageable) {
    const title = ui.recordTitle(record);
    return `<article class="v3-record-row"><button class="v3-record-open" data-action="open-record" data-id="${esc(ui, record.id)}"><span class="v3-record-thumb"><img src="${esc(ui, ui.image((record.photoIds || [0])[0], 'original'))}" alt="" draggable="false"></span><span class="v3-record-copy"><strong>${esc(ui, title)}</strong><span class="v3-record-meta">${esc(ui, formatDate(record, state, ui))} · ${countLabel(ui, (record.photoIds || []).length)}</span>${recordStates(record, ui, record.id === state.activeRecordId ? state.scenario : 'ready')}</span>${manageable ? '' : ui.icon('chevron', 18)}</button>${manageable ? `<button class="v3-icon-button v3-record-more" data-action="history-menu" data-id="${esc(ui, record.id)}" aria-expanded="${state.historyMenu === record.id}" aria-label="${esc(ui, text(ui, 'Manage record', '管理此记录', 'この記録を管理', '이 기록 관리', 'Gestionar registro'))}">•••</button>${state.historyMenu === record.id ? `<div class="v3-popover" role="menu"><button role="menuitem" data-action="delete-record" data-id="${esc(ui, record.id)}">${ui.icon('trash', 17)}${ui.t('delete')}</button></div>` : ''}` : ''}</article>`;
  }
  function emptyRecords(ui) {
    return `<div class="v3-empty"><span class="v3-empty-icon">${ui.icon('history', 27)}</span><h2>${ui.t('noHistory')}</h2><p>${ui.t('noRecent')}</p></div>`;
  }
  function capture(state, ui, forceWelcome) {
    const records = state.scenario === 'empty' ? [] : orderedRecords(state).slice(0, 3);
    const showWelcome = forceWelcome || !state.welcomeDismissed;
    return `<div class="page-scroll v3-page v3-capture"><header class="v3-brand-row"><span class="v3-brand"><span class="a-brand-seal" aria-hidden="true">sf</span>SeeFood</span><button class="v3-language" data-page="language">${ui.icon('globe', 17)}${languages[state.lang] || languages.en}</button></header><section class="v3-capture-hero"><div><h1>${text(ui, 'A good meal starts here.', '好好吃一顿，<br>从看懂开始。', 'わかると、<br>もっとおいしい。', '이해하면,<br>더 맛있는 한 끼.', 'Una buena comida empieza aquí.')}</h1><p>${text(ui, 'Make yourself at home, at any table.', '看懂菜单，把想说的话说明白。', 'メニューを読んで、伝えたいことを。', '메뉴를 읽고, 원하는 말을 전하세요.', 'Entiende el menú y encuentra tus palabras.')}</p></div><div class="v3-hero-art">${window.SeeFoodTableScene || ''}</div></section>${showWelcome ? `<aside class="v3-welcome-note"><span>${text(ui, 'Welcome. You can start right away.', '欢迎，直接开始就好。', 'ようこそ。そのまま始められます。', '환영해요. 바로 시작할 수 있어요.', 'Te damos la bienvenida. Ya puedes empezar.')}</span><div><button class="v3-text-button" data-page="preferences">${text(ui, 'Set dietary needs', '设置饮食偏好', '食事の希望を設定', '식사 선호 설정', 'Ajustar preferencias')}</button><button class="v3-icon-button" data-action="dismiss-welcome" aria-label="${esc(ui, text(ui, 'Dismiss welcome', '关闭引导', '案内を閉じる', '안내 닫기', 'Cerrar bienvenida'))}">${ui.icon('close', 17)}</button></div></aside>` : ''}<section class="v3-input-section">${mode(state, ui)}<p class="v3-mode-note">${ui.t(state.inputMode === 'dish' ? 'dishNote' : 'menuNote')}</p><div class="v3-input-actions"><button class="a-primary" data-action="take-photo">${ui.icon('camera', 21)}<span>${ui.t('takePhoto')}</span></button><button class="a-secondary" data-action="import-photos">${ui.icon('image', 21)}<span>${ui.t('importPhotos')}</span></button></div>${state.scenario === 'camera-denied' ? `<div class="v3-notice" role="status">${ui.icon('warning', 18)}<p>${ui.t('cameraUnavailable')}</p></div>` : ''}</section><section class="v3-recent-section"><div class="v3-section-heading"><h2>${ui.t('recent')}</h2><button class="v3-text-button" data-page="history">${ui.t('viewAll')}${ui.icon('chevron', 16)}</button></div>${records.length ? `<div class="v3-record-list">${records.map(record => recordRow(record, state, ui, false)).join('')}</div>` : emptyRecords(ui)}</section></div>${ui.tabbar('capture')}`;
  }
  function preview(state, ui) {
    const images = state.previewImages || [];
    const record = currentRecord(state);
    return `${ui.header('preview')}<div class="v3-preview-context"><span class="v3-context-label">${ui.icon(state.adding ? 'plus' : 'book', 17)}${ui.t(state.adding ? 'appendRecord' : 'newRecord')}</span>${state.adding && record ? `<strong>${esc(ui, ui.recordTitle(record))}</strong>` : ''}</div><div class="page-scroll v3-page v3-preview"><p class="v3-intro">${text(ui, 'Tap a photo to check it. Drag the handle to change its order.', '轻点图片查看大图，拖动把手调整顺序。', '写真をタップして確認し、ハンドルをドラッグして並べ替えます。', '사진을 눌러 확인하고 손잡이를 끌어 순서를 바꾸세요.', 'Toca una foto para revisarla. Arrastra el asa para ordenar.')}</p><ol class="v3-photo-list">${images.map((image, index) => `<li class="v3-photo-item" data-photo-index="${index}"><button class="v3-preview-photo" data-action="preview-image" data-index="${index}" aria-label="${esc(ui, `${ui.t('photo')} ${index + 1} · ${ui.t('zoomIn')}`)}"><img src="${esc(ui, ui.image(image, 'original'))}" alt="${esc(ui, `${ui.t('photo')} ${index + 1}`)}" draggable="false"><span>${String(index + 1).padStart(2, '0')}</span></button><div class="v3-photo-description"><strong>${ui.t('photo')} ${index + 1}</strong><span>${ui.t(state.inputMode === 'dish' ? 'dish' : 'menu')}</span><div class="v3-photo-order"><button data-action="move-photo" data-index="${index}" data-value="-1" aria-label="${ui.t('moveUp')}" ${index === 0 ? 'disabled' : ''}>↑</button><button data-action="move-photo" data-index="${index}" data-value="1" aria-label="${ui.t('moveDown')}" ${index === images.length - 1 ? 'disabled' : ''}>↓</button></div></div><div class="v3-photo-tools"><button class="v3-icon-button" data-action="remove-photo" data-index="${index}" aria-label="${esc(ui, `${ui.t('remove')} ${ui.t('photo')} ${index + 1}`)}">${ui.icon('close', 18)}</button><button class="v3-drag-handle" data-photo-drag="${index}" aria-label="${esc(ui, text(ui, `Drag photo ${index + 1} to reorder`, `拖动图片 ${index + 1} 调整顺序`, `写真 ${index + 1} をドラッグして並べ替え`, `사진 ${index + 1}을 끌어 순서 변경`, `Arrastra la foto ${index + 1} para ordenar`))}"><span aria-hidden="true">⠿</span></button></div></li>`).join('')}</ol>${!images.length ? `<div class="v3-empty">${ui.icon('image', 28)}<h2>${text(ui, 'No photos selected', '还没有要提交的图片', '写真が選択されていません', '선택한 사진이 없어요', 'No hay fotos seleccionadas')}</h2><p>${text(ui, 'Return to choose your photos.', '返回后可以重新选择图片。', '戻って写真を選んでください。', '돌아가서 사진을 선택하세요.', 'Vuelve para elegir tus fotos.')}</p></div>` : ''}${state.scenario === 'upload-failed' ? ui.status(record) : ''}</div><footer class="v3-footer"><button class="primary-button" data-action="submit-photos" ${images.length ? '' : 'disabled'}>${ui.t('confirmPhotos')}<span class="v3-button-count">${countLabel(ui, images.length)}</span></button><button class="v3-text-button v3-full-button" data-action="back">${ui.t('cancel')}</button></footer>`;
  }
  function preferenceSummary(state, ui) {
    const selected = state.preferences || [];
    const notes = state.preferenceNotes || {};
    const hasContent = selected.length > 0 || Object.values(notes).some(value => String(value || '').trim());
    if (!hasContent) return `<p>${text(ui, 'Tell us about allergies, dietary needs and the flavors you enjoy.', '告诉我们你的过敏信息、饮食限制和口味偏好。', 'アレルギー、食事の制限や好みを登録できます。', '알레르기, 식사 제한과 좋아하는 맛을 알려주세요.', 'Indica tus alergias, necesidades y sabores preferidos.')}</p>`;
    return `<div class="v3-preference-summary">${groups.map(group => {
      const groupOptions = group.options.filter(value => selected.includes(value));
      const note = String(notes[group.key] || '').trim();
      if (!groupOptions.length && !note) return '';
      return `<div><span>${ui.t(group.key)}</span><strong>${esc(ui, [...groupOptions.map(key => ui.t(key)), note].filter(Boolean).join(text(ui, ' · ', '、', '・', ' · ', ' · ')))}</strong></div>`;
    }).join('')}</div>`;
  }
  function mine(state, ui) {
    const count = (state.records || []).length;
    return `<div class="page-scroll v3-page v3-mine"><header class="v3-title-row"><h1>${ui.t('mine')}</h1><span class="a-brand-seal" aria-hidden="true">sf</span></header><section class="v3-preference-panel"><div class="v3-section-heading"><h2>${ui.t('preferences')}</h2>${ui.icon('leaf', 20)}</div>${preferenceSummary(state, ui)}<button class="v3-panel-action" data-page="preferences">${state.preferenceSet ? ui.t('edit') : text(ui, 'Set preferences', '设置偏好', '希望を設定', '선호 설정', 'Configurar preferencias')}${ui.icon('arrow', 17)}</button></section><div class="v3-settings-list"><button data-page="history"><span class="v3-setting-icon">${ui.icon('history', 21)}</span><span><strong>${ui.t('history')}</strong><small>${text(ui, `${count} saved record${count === 1 ? '' : 's'}`, `${count} 条记录`, `${count} 件の記録`, `기록 ${count}개`, `${count} registro${count === 1 ? '' : 's'}`)}</small></span>${ui.icon('chevron', 18)}</button><button data-page="language"><span class="v3-setting-icon">${ui.icon('globe', 21)}</span><span><strong>${ui.t('language')}</strong><small>${languages[state.lang] || languages.en}</small></span>${ui.icon('chevron', 18)}</button><button data-page="history" data-section="local-data"><span class="v3-setting-icon">${ui.icon('book', 21)}</span><span><strong>${text(ui, 'On this device', '本机数据', 'この端末のデータ', '이 기기의 데이터', 'Datos de este dispositivo')}</strong><small>${text(ui, 'Review and manage your saved records', '查看与管理已保存的记录', '保存した記録を確認・管理', '저장된 기록 확인 및 관리', 'Revisa y gestiona tus registros')}</small></span>${ui.icon('chevron', 18)}</button></div><p class="v3-local-note">${ui.icon('check', 16)}<span>${ui.t('localOnly')}</span></p></div>${ui.tabbar('mine')}`;
  }
  function history(state, ui) {
    const records = state.scenario === 'empty' ? [] : orderedRecords(state);
    return `${ui.header('history')}<div class="v3-history-tools"><span>${text(ui, 'Newest first', '按创建时间倒序', '新しい記録から表示', '최근 생성 순', 'Más recientes primero')}</span><button class="v3-text-button" data-action="history-menu" data-value="all" aria-expanded="${state.historyMenu === 'all'}" ${records.length ? '' : 'disabled'}>${text(ui, 'Manage', '管理', '管理', '관리', 'Gestionar')}</button>${state.historyMenu === 'all' ? `<div class="v3-popover v3-history-manage" role="menu"><button role="menuitem" data-action="clear-history">${ui.icon('trash', 17)}${ui.t('clearHistory')}</button></div>` : ''}</div><div class="page-scroll v3-page v3-history">${records.length ? `<div class="v3-record-list">${records.map(record => recordRow(record, state, ui, true)).join('')}</div>` : `${emptyRecords(ui)}<button class="primary-button" data-page="capture">${ui.icon('camera', 18)}${ui.t('takePhoto')}</button>`}<p class="v3-local-note">${ui.icon('book', 16)}<span>${ui.t('localOnly')}</span></p>${state.scenario === 'offline' ? ui.status() : ''}</div>`;
  }
  function preferences(state, ui) {
    const selected = state.preferences || [];
    const notes = state.preferenceNotes || {};
    return `${ui.header('preferences')}<div class="page-scroll v3-page v3-preferences"><p class="v3-intro">${ui.t('preferenceHelp')}</p>${['checking', 'failed'].includes(state.scenario) ? ui.status() : ''}${groups.map((group, index) => `<section class="v3-preference-group"><div class="v3-preference-group-title"><span>${String(index + 1).padStart(2, '0')}</span><h2>${ui.t(group.key)}</h2></div><div class="selection-chips v3-preference-chips">${group.options.map(value => `<button data-action="preference" data-value="${value}" class="${selected.includes(value) ? 'active' : ''}" aria-pressed="${selected.includes(value)}">${selected.includes(value) ? ui.icon('check', 15) : '<span class="v3-option-ring" aria-hidden="true"></span>'}${ui.t(value)}</button>`).join('')}</div><div class="form-field"><label for="v3-note-${group.key}">${ui.t('additional')} <span>${ui.t('optional')}</span></label><textarea id="v3-note-${group.key}" data-pref-note="${group.key}" rows="2" placeholder="${esc(ui, text(ui, 'Add anything else here', '在这里补充具体说明', '具体的な内容を追記', '구체적인 내용을 적어주세요', 'Añade más detalles'))}">${esc(ui, notes[group.key] || '')}</textarea></div></section>`).join('')}</div><footer class="v3-footer"><button class="primary-button" data-action="save-preferences">${ui.t('save')}</button>${!state.preferenceSet ? `<button class="v3-text-button v3-full-button" data-action="back">${ui.t('skip')}</button>` : ''}</footer>`;
  }
  function language(state, ui) {
    const firstChoice = ['unmatched-language', 'language-unmatched'].includes(state.scenario);
    return `${ui.header('language')}<div class="page-scroll v3-page v3-language-page"><span class="v3-language-symbol" aria-hidden="true">文<span>A</span></span><h2>${ui.t('chooseLanguage')}</h2><p class="v3-intro">${firstChoice ? text(ui, 'Choose a language to get started.', '先选择一种语言，即可开始。', '言語を選んで始めましょう。', '언어를 선택하면 시작할 수 있어요.', 'Elige un idioma para empezar.') : ui.t('languageNote')}</p><div class="v3-language-list">${Object.entries(languages).map(([code, label]) => `<button data-action="set-language" data-value="${code}" class="${code === state.lang ? 'is-active' : ''}" aria-pressed="${code === state.lang}"><span lang="${code}">${label}</span>${code === state.lang ? ui.icon('check', 20) : '<span class="v3-language-radio" aria-hidden="true"></span>'}</button>`).join('')}</div></div><footer class="v3-footer"><button class="primary-button" ${firstChoice ? 'data-page="capture"' : 'data-action="back"'}>${firstChoice ? text(ui, 'Start using SeeFood', '开始使用', 'SeeFood を始める', 'SeeFood 시작하기', 'Empezar a usar SeeFood') : ui.t('continue')}</button></footer>`;
  }
  function fullscreen(state, ui) {
    const fromPreview = state.fullImageSource === 'preview';
    const record = currentRecord(state);
    const images = fromPreview ? state.previewImages || [] : record?.photoIds || [];
    const index = Math.min(Math.max(0, Number(state.fullImageIndex ?? state.activeImage) || 0), Math.max(0, images.length - 1));
    const view = fromPreview ? 'original' : state.imageView || 'original';
    const zoom = Math.max(1, Math.min(4, Number(state.zoom) || 1));
    const unavailable = !fromPreview && state.scenario === 'offline-missing';
    return `<header class="v3-viewer-header"><button class="v3-icon-button" data-action="back" aria-label="${ui.t('back')}">${ui.icon('close', 22)}</button><h1>${text(ui, `Photo ${index + 1} of ${images.length}`, `图片 ${index + 1} / ${images.length}`, `写真 ${index + 1} / ${images.length}`, `사진 ${index + 1} / ${images.length}`, `Foto ${index + 1} de ${images.length}`)}</h1><span>${ui.t(view)}</span></header>${!fromPreview ? `<div class="v3-viewer-switch" role="group" aria-label="${esc(ui, text(ui, 'Image version', '图片版本', '画像の種類', '이미지 버전', 'Versión de la imagen'))}">${['original', 'translated'].map(value => `<button data-action="image-view" data-value="${value}" class="${view === value ? 'is-active' : ''}" aria-pressed="${view === value}">${ui.t(value)}</button>`).join('')}</div>` : ''}<div class="page-scroll image-viewer v3-full-image-scroll" data-image-scroll>${unavailable ? `<div class="v3-viewer-empty">${ui.icon('image', 30)}<p>${ui.t('notSavedImage')}</p></div>` : images.length ? `<img id="full-image" src="${esc(ui, ui.image(images[index], view))}" style="width:${zoom * 100}%" alt="${esc(ui, `${ui.t(view)} · ${ui.t('photo')} ${index + 1}`)}" draggable="false">` : ''}</div><div class="v3-viewer-footer"><div class="v3-viewer-thumbnails" aria-label="${esc(ui, text(ui, 'Select photo', '选择图片', '写真を選ぶ', '사진 선택', 'Seleccionar foto'))}">${images.map((image, number) => `<button data-action="full-select" data-index="${number}" class="${index === number ? 'is-active' : ''}" aria-pressed="${index === number}" aria-label="${esc(ui, `${ui.t('photo')} ${number + 1}`)}"><img src="${esc(ui, ui.image(image, 'original'))}" alt="" draggable="false"><span>${number + 1}</span></button>`).join('')}</div><div class="v3-viewer-zoom"><button data-action="zoom" data-value="-0.5" aria-label="${ui.t('zoomOut')}" ${zoom <= 1 ? 'disabled' : ''}>−</button><button data-action="zoom-reset">${Math.round(zoom * 100)}%</button><button data-action="zoom" data-value="0.5" aria-label="${ui.t('zoomIn')}" ${zoom >= 4 ? 'disabled' : ''}>+</button></div></div>`;
  }

  const pages = { capture, mine, preview, history, preferences, language, fullscreen, onboarding: (state, ui) => state.scenario === 'unmatched-language' ? language(state, ui) : capture(state, ui, true) };
  window.SeeFoodPagesV3 = { render(page, state, ui) { return pages[page] ? pages[page](state, ui) : null; } };
})();
